// ============================================================
// المتغيرات العالمية
// ============================================================
const refInvoices = db.ref('invoices');
const refCustomers = db.ref('customers');
const refInvoiceCounter = db.ref('invoiceCounter');
const refPayments = db.ref('payments');
const refItemsCatalog = db.ref('itemsCatalog');

let invoices = [];
let customers = [];
let invoiceCounter = 0;
let paymentsLog = [];
let itemsCatalog = [];

let currentEditingInvoiceId = null;
let ignoreStatusChange = false;

// ============================================================
// حالة الاتصال بالإنترنت
// ============================================================
let isOnline = navigator.onLine;
window.addEventListener('online', () => {
    isOnline = true;
    showToast('تم استعادة الاتصال بالإنترنت. جاري المزامنة...', 'success');
    syncToFirebase();
});
window.addEventListener('offline', () => {
    isOnline = false;
    showToast('أنت غير متصل بالإنترنت. البيانات ستحفظ محلياً.', 'error');
});

// ============================================================
// دوال التخزين المحلي المساعدة
// ============================================================
function localGet(key, fallback) {
    try {
        const data = localStorage.getItem(key);
        return data ? JSON.parse(data) : fallback;
    } catch (e) {
        return fallback;
    }
}
function localSet(key, value) {
    localStorage.setItem(key, JSON.stringify(value));
}

// ============================================================
// طبقة البيانات الهجينة (Firebase + localStorage)
// ============================================================
async function loadAllData() {
    if (navigator.onLine) {
        try {
            const snapInvoices = await refInvoices.once('value');
            invoices = snapInvoices.val() || [];
            const snapCustomers = await refCustomers.once('value');
            customers = snapCustomers.val() || [];
            const snapCounter = await refInvoiceCounter.once('value');
            invoiceCounter = snapCounter.val() || 0;
            const snapPayments = await refPayments.once('value');
            paymentsLog = snapPayments.val() || [];
            const snapCatalog = await refItemsCatalog.once('value');
            itemsCatalog = snapCatalog.val() || [];
            saveLocalData();
            console.log('✅ تم تحميل البيانات من Firebase');
        } catch (error) {
            console.error('❌ فشل تحميل البيانات من Firebase:', error);
            loadLocalData();
        }
    } else {
        loadLocalData();
    }
}

function loadLocalData() {
    invoices = localGet('invoices', []);
    customers = localGet('customers', []);
    invoiceCounter = localGet('invoiceCounter', 0);
    paymentsLog = localGet('paymentsLog', []);
    itemsCatalog = localGet('itemsCatalog', []);
    console.log('📦 تم تحميل البيانات من التخزين المحلي');
}

function saveAll() {
    saveLocalData();
    if (navigator.onLine) {
        syncToFirebase();
    } else {
        localStorage.setItem('pendingSync', 'true');
    }
}

function saveLocalData() {
    localSet('invoices', invoices);
    localSet('customers', customers);
    localSet('invoiceCounter', invoiceCounter);
    localSet('paymentsLog', paymentsLog);
    localSet('itemsCatalog', itemsCatalog);
}

async function syncToFirebase() {
    try {
        await refInvoices.set(invoices);
        await refCustomers.set(customers);
        await refInvoiceCounter.set(invoiceCounter);
        await refPayments.set(paymentsLog);
        await refItemsCatalog.set(itemsCatalog);
        localStorage.removeItem('pendingSync');
        console.log('☁️ تمت المزامنة مع Firebase');
    } catch (e) {
        console.error('فشلت المزامنة:', e);
    }
}

// ============================================================
// الشعار الافتراضي (Base64) – ضع كود Base64 لشعارك هنا
// ============================================================
const DEFAULT_LOGO_BASE64 = 'data:image/png;base64,'; // ← ضع كود base64 لشعارك إن أردت

let logoBase64 = '';

function loadLogoAsBase64() {
    return new Promise((resolve) => {
        if (DEFAULT_LOGO_BASE64 && DEFAULT_LOGO_BASE64.startsWith('data:image')) {
            resolve(DEFAULT_LOGO_BASE64);
            return;
        }
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.naturalWidth;
            canvas.height = img.naturalHeight;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);
            try {
                const dataURL = canvas.toDataURL('image/png');
                resolve(dataURL);
            } catch (e) { console.warn('⚠️ تعذّر تحويل الشعار'); resolve(''); }
        };
        img.onerror = () => { console.warn('⚠️ لم يتم العثور على logo.png'); resolve(''); };
        img.src = 'logo.png';
    });
}

// ============================================================
// TOAST
// ============================================================
function showToast(msg, type = 'success') {
    const t = document.getElementById('toast');
    t.textContent = msg;
    t.className = 'toast ' + type + ' show';
    clearTimeout(t._timeout);
    t._timeout = setTimeout(() => t.classList.remove('show'), 3000);
}

// ============================================================
// تنسيق التاريخ
// ============================================================
function formatDateDisplay(dateStr) {
    if (!dateStr) return '';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    return parts[2] + '/' + parts[1] + '/' + parts[0];
}

// ============================================================
// شاشة البداية
// ============================================================
function showSplash(logo) {
    const splash = document.getElementById('splash-screen');
    const logoImg = document.getElementById('splash-logo');
    const logoFallback = document.getElementById('splash-logo-fallback');

    if (logo && logo.startsWith('data:image')) {
        logoImg.src = logo;
        logoImg.style.display = 'block';
        logoFallback.style.display = 'none';
    } else {
        logoImg.style.display = 'none';
        logoFallback.style.display = 'block';
    }

    setTimeout(() => {
        splash.classList.add('fade-out');
        document.getElementById('main-app').style.display = 'block';
        setTimeout(() => {
            splash.style.display = 'none';
        }, 600);
    }, 1800);
}

// ============================================================
// التنقل بين المشاهدات
// ============================================================
document.querySelectorAll('.dash-card').forEach(card => {
    card.addEventListener('click', function () {
        document.querySelectorAll('.dash-card').forEach(c => c.classList.remove('active'));
        this.classList.add('active');
        const view = this.dataset.view;
        document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
        document.getElementById('view-' + view).classList.add('active');
        if (view === 'invoices') renderInvoices();
        if (view === 'customers') renderCustomers();
        updateHeaderTotal();
    });
});

// ============================================================
// الاقتراحات للأصناف
// ============================================================
function updateSuggestionsDatalist(filterText) {
    const dl = document.getElementById('itemSuggestions');
    if (!dl) return;
    dl.innerHTML = '';
    if (!filterText.trim()) return;
    const term = filterText.trim().toLowerCase();
    const matches = itemsCatalog.filter(item => item.name.toLowerCase().startsWith(term));
    matches.forEach(item => {
        const opt = document.createElement('option');
        opt.value = item.name;
        dl.appendChild(opt);
    });
}

function autoFillItemPrice(inputElement) {
    const row = inputElement.closest('tr');
    const name = inputElement.value.trim();
    if (!name) return;
    const found = itemsCatalog.find(item => item.name.toLowerCase() === name.toLowerCase());
    if (found) {
        const priceInput = row.querySelector('.item-price');
        priceInput.value = found.price;
        calcInvoice();
    }
}

function handleItemNameInput(e) {
    updateSuggestionsDatalist(e.target.value);
    autoFillItemPrice(e.target);
}

// ============================================================
// صفوف الأصناف في الفاتورة
// ============================================================
function addItemRow(item) {
    const tbody = document.getElementById('itemsBody');
    const row = document.createElement('tr');

    const isNew = !item;
    const name = item ? item.name : '';
    const cases = item ? (item.cases || 0) : 0;
    const pieces = item ? (item.pieces || 0) : 0;
    const qty = item ? (item.qty || 1) : 1;
    const price = item ? item.price : 0;
    const itemDiscount = item ? (item.itemDiscount || 0) : 0;
    const total = (qty * price) - itemDiscount;

    row.innerHTML = `
        <td><input type="text" class="item-name" value="${name}" placeholder="اسم الصنف" list="itemSuggestions"></td>
        <td><input type="number" class="item-cases" value="${isNew ? '' : cases}" placeholder="0" min="0" step="1"></td>
        <td><input type="number" class="item-pieces" value="${isNew ? '' : pieces}" placeholder="0" min="0" step="1"></td>
        <td><input type="number" class="item-qty" value="${isNew ? '' : qty}" placeholder="0" min="0" step="1"></td>
        <td><input type="number" class="item-price" value="${isNew ? '' : price}" placeholder="0" min="0" step="0.01"></td>
        <td class="item-total">${total.toFixed(2)}</td>
        <td><input type="number" class="item-discount" value="${isNew ? '' : itemDiscount}" placeholder="0" min="0" step="0.01"></td>
        <td><button class="remove-btn" onclick="removeItemRow(this)">✕</button></td>
    `;
    tbody.appendChild(row);
    attachItemListeners(row);
    calcInvoice();
}

function removeItemRow(btn) {
    const tr = btn.closest('tr');
    if (document.getElementById('itemsBody').children.length <= 1) {
        showToast('يجب أن يوجد صنف واحد على الأقل', 'error');
        return;
    }
    tr.remove();
    calcInvoice();
}

function attachItemListeners(row) {
    const casesInput = row.querySelector('.item-cases');
    const piecesInput = row.querySelector('.item-pieces');
    const qtyInput = row.querySelector('.item-qty');
    const priceInput = row.querySelector('.item-price');
    const discountInput = row.querySelector('.item-discount');
    const nameInput = row.querySelector('.item-name');

    nameInput.addEventListener('input', handleItemNameInput);

    let updatingFromCasePieces = false;
    let updatingFromQty = false;

    const updateQtyFromCasePieces = () => {
        if (updatingFromQty) return;
        updatingFromCasePieces = true;
        const c = parseFloat(casesInput.value) || 0;
        const p = parseFloat(piecesInput.value) || 0;
        qtyInput.value = c * p;
        updatingFromCasePieces = false;
        calcInvoice();
    };

    casesInput.addEventListener('input', updateQtyFromCasePieces);
    piecesInput.addEventListener('input', updateQtyFromCasePieces);

    qtyInput.addEventListener('input', () => {
        if (updatingFromCasePieces) return;
        updatingFromQty = true;
        casesInput.value = 0;
        piecesInput.value = 0;
        updatingFromQty = false;
        calcInvoice();
    });

    priceInput.addEventListener('input', calcInvoice);
    discountInput.addEventListener('input', calcInvoice);
}

// ============================================================
// حسابات الفاتورة
// ============================================================
function calcInvoice() {
    const rows = document.querySelectorAll('#itemsBody tr');
    let subtotal = 0;
    rows.forEach(row => {
        const qty = parseFloat(row.querySelector('.item-qty').value) || 0;
        const price = parseFloat(row.querySelector('.item-price').value) || 0;
        const discount = parseFloat(row.querySelector('.item-discount').value) || 0;
        const total = Math.max(0, (qty * price) - discount);
        row.querySelector('.item-total').textContent = total.toFixed(2);
        subtotal += total;
    });
    document.getElementById('subtotalDisplay').textContent = subtotal.toFixed(2);

    const discountPercent = parseFloat(document.getElementById('discountInput').value) || 0;
    const discountValue = (subtotal * discountPercent) / 100;
    const netTotal = Math.max(0, subtotal - discountValue);
    document.getElementById('totalAfterDiscount').textContent = netTotal.toFixed(2);

    const paymentInput = document.getElementById('paymentInput');
    const remainingDisplay = document.getElementById('remainingDisplay');
    let payment = parseFloat(paymentInput.value) || 0;
    if (payment > netTotal) {
        payment = netTotal;
        paymentInput.value = netTotal.toFixed(2);
        showToast('لا يمكن أن يتجاوز المبلغ المدفوع الصافي النهائي', 'error');
    }
    const remaining = Math.max(0, netTotal - payment);
    remainingDisplay.textContent = remaining.toFixed(2);

    return { subtotal, discountPercent, discountValue, netTotal, payment, remaining };
}

// ============================================================
// التعامل مع حالة الدفع
// ============================================================
function updatePaymentByStatus() {
    if (ignoreStatusChange) return;
    const status = document.getElementById('paymentStatus').value;
    const netTotal = parseFloat(document.getElementById('totalAfterDiscount').textContent) || 0;
    const paymentInput = document.getElementById('paymentInput');

    if (status === 'مدفوعة') {
        paymentInput.value = netTotal.toFixed(2);
        paymentInput.disabled = true;
    } else if (status === 'دين كامل') {
        paymentInput.value = '0';
        paymentInput.disabled = true;
    } else {
        paymentInput.disabled = false;
    }
    calcInvoice();
}

document.getElementById('paymentStatus').addEventListener('change', updatePaymentByStatus);
document.getElementById('paymentInput').addEventListener('input', function () {
    const netTotal = parseFloat(document.getElementById('totalAfterDiscount').textContent) || 0;
    if (parseFloat(this.value) > netTotal) {
        this.value = netTotal.toFixed(2);
        showToast('المبلغ المدفوع لا يمكن أن يتجاوز الصافي النهائي', 'error');
    }
    calcInvoice();
});

// ============================================================
// حفظ الفاتورة
// ============================================================
function saveInvoice() {
    const customer = document.getElementById('invCustomer').value.trim();
    const address = document.getElementById('invAddress').value.trim();
    const date = document.getElementById('invDate').value;
    if (!customer) { showToast('الرجاء إدخال اسم العميل', 'error'); return; }
    if (!date) { showToast('الرجاء اختيار التاريخ', 'error'); return; }

    const rows = document.querySelectorAll('#itemsBody tr');
    if (rows.length === 0) { showToast('الرجاء إضافة صنف واحد على الأقل', 'error'); return; }

    const items = [];
    let valid = true;
    rows.forEach(row => {
        const name = row.querySelector('.item-name').value.trim();
        const cases = parseFloat(row.querySelector('.item-cases').value) || 0;
        const pieces = parseFloat(row.querySelector('.item-pieces').value) || 0;
        const qty = parseFloat(row.querySelector('.item-qty').value) || 0;
        const price = parseFloat(row.querySelector('.item-price').value) || 0;
        const itemDiscount = parseFloat(row.querySelector('.item-discount').value) || 0;
        const total = Math.max(0, (qty * price) - itemDiscount);
        if (!name) { valid = false; return; }
        items.push({ name, cases, pieces, qty, price, itemDiscount, total });
    });
    if (!valid || items.length === 0) { showToast('الرجاء إدخال اسم لكل صنف', 'error'); return; }

    const { subtotal, discountPercent, discountValue, netTotal, payment, remaining } = calcInvoice();
    const paymentStatus = document.getElementById('paymentStatus').value;

    // تحديث كتالوج الأصناف
    const nameToPrice = {};
    items.forEach(item => {
        if (item.name) nameToPrice[item.name.toLowerCase()] = { name: item.name, price: item.price };
    });
    for (const key in nameToPrice) {
        const entry = nameToPrice[key];
        const existingIndex = itemsCatalog.findIndex(cat => cat.name.toLowerCase() === entry.name.toLowerCase());
        if (existingIndex >= 0) itemsCatalog[existingIndex].price = entry.price;
        else itemsCatalog.push({ name: entry.name, price: entry.price });
    }

    // إضافة العميل إن لم يكن موجوداً
    if (!customers.some(c => c.name.toLowerCase() === customer.toLowerCase())) {
        customers.push({
            id: Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 4),
            name: customer,
            phone: '',
            address: address,
            createdAt: new Date().toISOString()
        });
        updateCustomerList();
    } else {
        const existingCust = customers.find(c => c.name.toLowerCase() === customer.toLowerCase());
        if (existingCust && address) existingCust.address = address;
    }

    if (currentEditingInvoiceId) {
        const index = invoices.findIndex(inv => inv.id === currentEditingInvoiceId);
        if (index === -1) { showToast('الفاتورة غير موجودة', 'error'); return; }
        invoices[index] = {
            ...invoices[index],
            customer, address, date, items,
            subtotal, discountPercent, discountValue, netTotal,
            payment, remaining, paymentStatus
        };
        showToast('✅ تم تعديل الفاتورة ' + invoices[index].number);
    } else {
        invoiceCounter++;
        const invNumber = 'INV-' + String(invoiceCounter).padStart(4, '0');
        const invoice = {
            id: Date.now() + '_' + Math.random().toString(36).substr(2, 4),
            number: invNumber,
            customer, address, date, items,
            subtotal, discountPercent, discountValue, netTotal,
            payment, remaining, paymentStatus,
            createdAt: new Date().toISOString()
        };
        invoices.unshift(invoice);
        showToast('✅ تم حفظ الفاتورة ' + invNumber);
    }

    saveAll();
    renderInvoices();
    updateHeaderTotal();
    clearInvoiceForm();
}

function clearInvoiceForm() {
    document.getElementById('invCustomer').value = '';
    document.getElementById('invAddress').value = '';
    document.getElementById('invDate').value = new Date().toISOString().split('T')[0];
    const tbody = document.getElementById('itemsBody');
    tbody.innerHTML = '';
    addItemRow();
    document.getElementById('discountInput').value = 0;
    document.getElementById('paymentStatus').value = 'دين كامل';
    ignoreStatusChange = true;
    document.getElementById('paymentInput').value = 0;
    document.getElementById('paymentInput').disabled = true;
    ignoreStatusChange = false;
    currentEditingInvoiceId = null;
    calcInvoice();
    generateInvNumber();
}

function generateInvNumber() {
    if (!currentEditingInvoiceId) {
        document.getElementById('invNumber').value = 'INV-' + String(invoiceCounter + 1).padStart(4, '0');
    }
}

// ============================================================
// عرض الفواتير
// ============================================================
function renderInvoices() {
    const container = document.getElementById('invoicesContainer');
    const search = document.getElementById('invoiceSearch').value.trim().toLowerCase();

    let filtered = invoices;
    if (search) {
        filtered = invoices.filter(inv =>
            inv.number.toLowerCase().includes(search) ||
            inv.customer.toLowerCase().includes(search)
        );
    }

    if (filtered.length === 0) {
        container.innerHTML = `<div class="empty-state"><div class="empty-icon">📋</div><p>لا توجد فواتير${search ? ' مطابقة للبحث' : ''}</p></div>`;
        return;
    }

    let html = `<table class="data-table"><thead><tr>
        <th>رقم الفاتورة</th><th>العميل</th><th>التاريخ</th><th>المجموع</th><th>الحسم</th><th>الصافي</th><th>المدفوع</th><th>المتبقي</th><th>حالة الدفع</th><th>الإجراءات</th>
    </tr></thead><tbody>`;

    filtered.forEach(inv => {
        const netTotal = inv.netTotal !== undefined ? inv.netTotal : (inv.subtotal - (inv.discountValue || 0));
        const payment = inv.payment || 0;
        const remaining = inv.remaining !== undefined ? inv.remaining : (netTotal - payment);
        const status = inv.paymentStatus || getStatusFromAmounts(netTotal, payment);

        let badgeHtml = '';
        if (status === 'مدفوعة') badgeHtml = '<span class="badge badge-paid">مدفوعة</span>';
        else if (status === 'دين جزئي') badgeHtml = '<span class="badge badge-partial">دين جزئي</span>';
        else badgeHtml = '<span class="badge badge-unpaid">دين كامل</span>';

        html += `<tr>
            <td><strong>${inv.number}</strong></td>
            <td>${escHtml(inv.customer)}</td>
            <td>${formatDateDisplay(inv.date)}</td>
            <td>${inv.subtotal.toFixed(2)} $</td>
            <td>${(inv.discountPercent || 0).toFixed(2)}%</td>
            <td>${netTotal.toFixed(2)} $</td>
            <td>${payment.toFixed(2)} $</td>
            <td><strong>${remaining.toFixed(2)} $</strong></td>
            <td>${badgeHtml}</td>
            <td class="actions">
                <button class="btn btn-primary btn-xs" onclick="printInvoice('${inv.id}')">🖨️ طباعة</button>
                <button class="btn btn-warning btn-xs" onclick="editInvoice('${inv.id}')">✏️ تعديل</button>
                <button class="btn btn-danger btn-xs" onclick="deleteInvoice('${inv.id}')">🗑️ حذف</button>
            </td>
        </tr>`;
    });

    html += '</tbody></table>';
    container.innerHTML = html;
}

function getStatusFromAmounts(netTotal, payment) {
    if (payment >= netTotal && netTotal > 0) return 'مدفوعة';
    if (payment <= 0) return 'دين كامل';
    return 'دين جزئي';
}

function deleteInvoice(id) {
    if (!confirm('هل أنت متأكد من حذف هذه الفاتورة؟')) return;
    invoices = invoices.filter(inv => inv.id !== id);
    saveAll();
    renderInvoices();
    updateHeaderTotal();
    showToast('تم حذف الفاتورة');
}

function editInvoice(id) {
    const inv = invoices.find(i => i.id === id);
    if (!inv) { showToast('الفاتورة غير موجودة', 'error'); return; }

    document.querySelectorAll('.dash-card').forEach(c => c.classList.remove('active'));
    document.querySelector('[data-view="new-invoice"]').classList.add('active');
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-new-invoice').classList.add('active');

    document.getElementById('invCustomer').value = inv.customer;
    document.getElementById('invAddress').value = inv.address || '';
    document.getElementById('invDate').value = inv.date;
    document.getElementById('invNumber').value = inv.number;

    const tbody = document.getElementById('itemsBody');
    tbody.innerHTML = '';
    inv.items.forEach(item => addItemRow(item));
    document.getElementById('discountInput').value = inv.discountPercent || 0;

    ignoreStatusChange = true;
    const statusSelect = document.getElementById('paymentStatus');
    statusSelect.value = inv.paymentStatus || 'دين كامل';
    const paymentInput = document.getElementById('paymentInput');
    paymentInput.value = (inv.payment || 0).toFixed(2);
    if (statusSelect.value === 'مدفوعة' || statusSelect.value === 'دين كامل') {
        paymentInput.disabled = true;
    } else {
        paymentInput.disabled = false;
    }
    ignoreStatusChange = false;

    currentEditingInvoiceId = inv.id;
    calcInvoice();
    saveAll();
    showToast('📝 جاري تعديل الفاتورة ' + inv.number);
}

// ============================================================
// طباعة الفاتورة ومعاينة PDF (اللون الأزرق الداكن #0D47A1)
// ============================================================
function printInvoice(id) {
    const inv = invoices.find(i => i.id === id);
    if (!inv) { showToast('الفاتورة غير موجودة', 'error'); return; }

    const netTotal = inv.netTotal !== undefined ? inv.netTotal : (inv.subtotal - (inv.discountValue || 0));
    const payment = inv.payment || 0;
    const remaining = inv.remaining !== undefined ? inv.remaining : (netTotal - payment);
    const status = inv.paymentStatus || getStatusFromAmounts(netTotal, payment);

    const statusBadge = status === 'مدفوعة' ? 'badge-paid' : (status === 'دين جزئي' ? 'badge-partial' : 'badge-unpaid');
    const statusText = status === 'مدفوعة' ? 'مدفوعة' : (status === 'دين جزئي' ? 'دين جزئي' : 'دين كامل');

    const logoSrc = (logoBase64 && logoBase64.startsWith('data:image')) ? logoBase64 : '';
    const logoImg = logoSrc ? `<img src="${logoSrc}" class="header-logo" alt="شعار" style="max-height:130px; max-width:200px;">` : `<span style="font-size:3rem;">🏢</span>`;

    const hasItemDiscount = inv.items.some(item => (item.itemDiscount || 0) > 0);

    let itemsRows = '';
    inv.items.forEach(item => {
        const notes = (item.cases > 0 && item.pieces > 0) ? `${item.cases} × ${item.pieces}` : '';
        if (hasItemDiscount) {
            itemsRows += `<tr>
                <td>${escHtml(item.name)}</td><td>${item.qty}</td><td>${item.price.toFixed(2)} $</td>
                <td>${(item.qty * item.price).toFixed(2)} $</td><td>${(item.itemDiscount || 0).toFixed(2)} $</td>
                <td>${item.total.toFixed(2)} $</td><td>${notes}</td></tr>`;
        } else {
            itemsRows += `<tr>
                <td>${escHtml(item.name)}</td><td>${item.qty}</td><td>${item.price.toFixed(2)} $</td>
                <td>${item.total.toFixed(2)} $</td><td>${notes}</td></tr>`;
        }
    });

    let tableHead = hasItemDiscount
        ? `<tr><th>الصنف</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th><th>الخصم</th><th>الصافي</th><th>ملاحظات</th></tr>`
        : `<tr><th>الصنف</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th><th>ملاحظات</th></tr>`;

    let discountLines = '';
    if (inv.discountPercent > 0) {
        discountLines += `
            <div class="total-row"><span>نسبة الحسم:</span><span>${inv.discountPercent.toFixed(2)}%</span></div>
            <div class="total-row"><span>قيمة الحسم:</span><span>${inv.discountValue.toFixed(2)} $</span></div>`;
    }

    const address = inv.address || (customers.find(c => c.name.toLowerCase() === inv.customer.toLowerCase()) || {}).address || 'غير محدد';

    const html = `
        <div class="invoice-template" style="font-size: 1.05rem;">
            ${logoSrc ? `<div class="invoice-watermark" style="width:80%; max-width:600px;"><img src="${logoSrc}" alt="علامة مائية" style="width:100%; height:auto;"></div>` : ''}
            <div class="invoice-header" style="display:flex; flex-direction:row; justify-content:space-between; align-items:stretch; gap:15px; flex-wrap:nowrap; width:100%; box-sizing:border-box;">
                <div class="header-right" style="display:flex; flex-direction:column; justify-content:space-between; flex:1; text-align:right;">
                    <div style="flex:1; display:flex; flex-direction:column; justify-content:flex-start;">
                        <h2 style="color: #c00; font-size: 2rem; font-weight: 900; margin:0 0 4px 0;">سعيد ستندر</h2>
                        <p style="font-size:1.1rem; color: #0D47A1; margin:2px 0; line-height:1.8;">للصناعة والتجارة</p>
                        <p style="font-size:1.1rem; color: #0D47A1; margin:2px 0; line-height:1.8;">قساطل - اكسسوارات صحية</p>
                    </div>
                    <p class="invoice-number-header" style="margin-top:auto;">رقم الفاتورة: ${inv.number}</p>
                </div>
                <div class="header-center" style="flex:0 0 auto; display:flex; align-items:center; justify-content:center;">
                    ${logoImg}
                </div>
                <div class="header-left" style="display:flex; flex-direction:column; justify-content:space-between; flex:1; text-align:left;">
                    <div style="flex:1; display:flex; flex-direction:column; justify-content:flex-start;">
                        <div style="color: #c00; font-size: 2rem; font-weight: 900; margin:0 0 4px 0; line-height:1.3; visibility:hidden;">سعيد ستندر</div>
                        <p style="font-size:1.1rem; color: #0D47A1; margin:2px 0; line-height:1.8;">اعزاز - غربي دوار الساعة</p>
                        <p style="font-size:1.1rem; color: #0D47A1; margin:2px 0; line-height:1.8;">جانب كازية يا شام</p>
                    </div>
                    <p class="invoice-date-header" style="margin-top:auto;">تاريخ الفاتورة: ${formatDateDisplay(inv.date)}</p>
                </div>
            </div>
            <div class="customer-details">
                <p><strong>الزبون المحترم:</strong> ${escHtml(inv.customer)}</p>
                <p><strong>المقيم في:</strong> ${escHtml(address)}</p>
            </div>
            <table class="invoice-items-table"><thead>${tableHead}</thead><tbody>${itemsRows}</tbody></table>
            <div class="invoice-totals">
                <div class="total-row"><span>إجمالي الفاتورة (قبل الحسم):</span><span>${inv.subtotal.toFixed(2)} $</span></div>
                ${discountLines}
                <div class="total-row"><span>الصافي النهائي بعد الحسم:</span><span>${netTotal.toFixed(2)} $</span></div>
                <div class="total-row"><span>المدفوع:</span><span>${payment.toFixed(2)} $</span></div>
                <div class="total-row grand"><span>المتبقي:</span><span>${remaining.toFixed(2)} $</span></div>
                <div class="total-row"><span>حالة الدفع:</span><span class="payment-status badge ${statusBadge}">${statusText}</span></div>
            </div>
            <div class="invoice-footer"><p>شكراً لتعاملكم معنا</p></div>
        </div>
        <div class="invoice-actions">
            <button class="btn btn-primary" onclick="window.print()">🖨️ طباعة</button>
            <button class="btn btn-success" onclick="savePDF('${inv.number}')">💾 حفظ PDF</button>
            <button class="btn btn-warning" onclick="sharePDF('${inv.number}')">📤 مشاركة</button>
            <button class="btn btn-outline" onclick="closePrint()">✕ إغلاق</button>
        </div>`;

    document.getElementById('printInvoiceContent').innerHTML = html;
    document.getElementById('printArea').classList.add('show');
}

function closePrint() {
    document.getElementById('printArea').classList.remove('show');
}
document.getElementById('printArea').addEventListener('click', function (e) {
    if (e.target === this) closePrint();
});

// ============================================================
// توليد PDF (جودة عالية مع هوامش بيضاء وتخطيط ثابت)
// ============================================================
async function convertImagesToBase64(container) {
    const images = container.querySelectorAll('img');
    for (const img of images) {
        if (img.src.startsWith('data:')) continue;
        try {
            const blob = await fetch(img.src).then(r => r.blob());
            const dataURL = await new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            });
            img.src = dataURL;
        } catch (e) {
            console.warn(`⚠️ تعذّر تحويل الصورة: ${img.src}`);
            img.style.display = 'none';
        }
    }
}

async function generatePDFBlob(invoiceNumber) {
    const element = document.getElementById('printInvoiceContent');
    const clone = element.cloneNode(true);

    clone.style.width = '210mm';
    clone.style.minHeight = '297mm';
    clone.style.maxHeight = 'none';
    clone.style.overflow = 'hidden';
    clone.style.height = 'auto';
    clone.style.margin = '0';
    clone.style.padding = '15mm 12mm';
    clone.style.boxSizing = 'border-box';
    clone.style.backgroundColor = '#ffffff';

    const invoiceHeader = clone.querySelector('.invoice-header');
    if (invoiceHeader) {
        invoiceHeader.style.display = 'flex';
        invoiceHeader.style.flexDirection = 'row';
        invoiceHeader.style.justifyContent = 'space-between';
        invoiceHeader.style.alignItems = 'stretch';
        invoiceHeader.style.gap = '15px';
        invoiceHeader.style.flexWrap = 'nowrap';
        invoiceHeader.style.width = '100%';
        invoiceHeader.style.boxSizing = 'border-box';

        const headerRight = invoiceHeader.querySelector('.header-right');
        if (headerRight) {
            headerRight.style.textAlign = 'right';
            headerRight.style.flex = '1';
            headerRight.style.display = 'flex';
            headerRight.style.flexDirection = 'column';
            headerRight.style.justifyContent = 'space-between';
        }
        const headerCenter = invoiceHeader.querySelector('.header-center');
        if (headerCenter) {
            headerCenter.style.flex = '0 0 auto';
            headerCenter.style.textAlign = 'center';
        }
        const headerLeft = invoiceHeader.querySelector('.header-left');
        if (headerLeft) {
            headerLeft.style.textAlign = 'left';
            headerLeft.style.flex = '1';
            headerLeft.style.display = 'flex';
            headerLeft.style.flexDirection = 'column';
            headerLeft.style.justifyContent = 'space-between';
        }
    }

    const btns = clone.querySelectorAll('.invoice-actions button');
    btns.forEach(b => b.style.display = 'none');

    clone.style.position = 'absolute';
    clone.style.top = '-9999px';
    document.body.appendChild(clone);

    await convertImagesToBase64(clone);

    const canvas = await html2canvas(clone, {
        scale: 3,
        useCORS: true,
        allowTaint: false,
        logging: false,
        backgroundColor: '#ffffff',
        width: 210 * 3.779527559,
        height: 297 * 3.779527559 * 1.5
    });

    document.body.removeChild(clone);

    const croppedCanvas = cropCanvas(canvas);

    const imgData = croppedCanvas.toDataURL('image/jpeg', 0.95);
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF('p', 'mm', 'a4', { compress: true });
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = pdf.internal.pageSize.getHeight();

    const imgWidth = pdfWidth;
    const imgHeight = (croppedCanvas.height * imgWidth) / croppedCanvas.width;
    let heightLeft = imgHeight;
    let position = 0;

    pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, Math.min(imgHeight, pdfHeight));
    heightLeft -= pdfHeight;

    while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
        heightLeft -= pdfHeight;
    }

    return pdf.output('blob');
}

function cropCanvas(canvas) {
    const ctx = canvas.getContext('2d');
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const pixels = imageData.data;
    let lastContentRow = 0;

    for (let y = canvas.height - 1; y >= 0; y--) {
        let rowHasContent = false;
        for (let x = 0; x < canvas.width; x++) {
            const idx = (y * canvas.width + x) * 4;
            const r = pixels[idx];
            const g = pixels[idx + 1];
            const b = pixels[idx + 2];
            if (r < 240 || g < 240 || b < 240) {
                rowHasContent = true;
                break;
            }
        }
        if (rowHasContent) {
            lastContentRow = y + 1;
            break;
        }
    }

    const minHeight = canvas.height * 0.5;
    const newHeight = Math.max(lastContentRow, minHeight);

    const newCanvas = document.createElement('canvas');
    newCanvas.width = canvas.width;
    newCanvas.height = newHeight;
    const newCtx = newCanvas.getContext('2d');
    newCtx.drawImage(canvas, 0, 0, canvas.width, newHeight, 0, 0, canvas.width, newHeight);

    return newCanvas;
}

async function savePDF(invoiceNumber) {
    try {
        showToast('⏳ جاري إنشاء ملف PDF...', 'success');
        const blob = await generatePDFBlob(invoiceNumber);
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = invoiceNumber + '.pdf';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        showToast('✅ تم حفظ ملف PDF باسم ' + invoiceNumber + '.pdf');
    } catch (err) {
        showToast('❌ فشل إنشاء ملف PDF', 'error');
        console.error(err);
    }
}

async function sharePDF(invoiceNumber) {
    try {
        showToast('⏳ جاري تجهيز الملف للمشاركة...', 'success');
        const blob = await generatePDFBlob(invoiceNumber);
        const file = new File([blob], invoiceNumber + '.pdf', { type: 'application/pdf' });

        if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({ files: [file], title: `فاتورة ${invoiceNumber}`, text: `فاتورة ${invoiceNumber}` });
            showToast('✅ تم إرسال الفاتورة بنجاح');
        } else if (navigator.share) {
            await navigator.share({ title: `فاتورة ${invoiceNumber}`, text: `فاتورة ${invoiceNumber}` });
            showToast('✅ تمت المشاركة');
        } else {
            savePDF(invoiceNumber);
            alert('لا يدعم متصفحك المشاركة المباشرة. تم حفظ الملف.');
        }
    } catch (err) {
        if (err.name === 'AbortError') return;
        showToast('❌ فشلت المشاركة، جاري تحميل الملف', 'error');
        savePDF(invoiceNumber);
        console.error(err);
    }
}

// ============================================================
// إدارة العملاء والديون
// ============================================================
function getCustomerStats(customerName) {
    let totalInvoiced = 0, totalPaid = 0;
    invoices.forEach(inv => {
        if (inv.customer === customerName) {
            const net = inv.netTotal !== undefined ? inv.netTotal : (inv.subtotal - (inv.discountValue || 0));
            totalInvoiced += net;
            totalPaid += inv.payment || 0;
        }
    });
    const remaining = totalInvoiced - totalPaid;
    let status;
    if (remaining <= 0) status = 'مسدد';
    else if (totalPaid <= 0) status = 'دين كامل';
    else status = 'دين جزئي';
    return { totalInvoiced, totalPaid, remaining, status };
}

function allocatePayment(customerName, amount) {
    const unpaidInvoices = invoices
        .filter(inv => inv.customer === customerName && (inv.remaining || (inv.netTotal - (inv.payment || 0)) > 0))
        .sort((a, b) => new Date(a.date) - new Date(b.date));
    let remainingAmount = amount;
    const allocations = [];
    for (const inv of unpaidInvoices) {
        if (remainingAmount <= 0) break;
        const net = inv.netTotal !== undefined ? inv.netTotal : (inv.subtotal - (inv.discountValue || 0));
        const currentPaid = inv.payment || 0;
        const currentRemaining = net - currentPaid;
        const allocate = Math.min(remainingAmount, currentRemaining);
        if (allocate > 0) {
            inv.payment = currentPaid + allocate;
            inv.remaining = net - inv.payment;
            if (inv.remaining <= 0) inv.paymentStatus = 'مدفوعة';
            else if (inv.payment > 0) inv.paymentStatus = 'دين جزئي';
            else inv.paymentStatus = 'دين كامل';
            allocations.push({ invoiceId: inv.id, invoiceNumber: inv.number, amount: allocate });
            remainingAmount -= allocate;
        }
    }
    return allocations;
}

function addCustomerPayment(customerName, amount, notes) {
    if (amount <= 0) { showToast('المبلغ يجب أن يكون أكبر من صفر', 'error'); return; }
    const stats = getCustomerStats(customerName);
    if (amount > stats.remaining) {
        showToast('المبلغ أكبر من الدين المتبقي (' + stats.remaining.toFixed(2) + ' $)', 'error');
        return;
    }

    const allocations = allocatePayment(customerName, amount);
    if (allocations.length === 0) { showToast('لا توجد فواتير غير مسددة لهذا العميل', 'error'); return; }

    const paymentRecord = {
        id: Date.now().toString(36) + Math.random().toString(36).substr(2, 4),
        customerName,
        amount,
        notes: notes || '',
        datetime: new Date().toISOString(),
        allocations
    };
    paymentsLog.unshift(paymentRecord);

    saveAll();
    renderCustomers();
    updateHeaderTotal();
    showToast(`✅ تم إضافة دفعة بقيمة ${amount.toFixed(2)} $ بنجاح`);
    if (document.getElementById('customerDebtModal').classList.contains('show')) {
        openCustomerDebt(customerName);
    }
}

function renderCustomers() {
    const container = document.getElementById('customersContainer');
    const searchInput = document.getElementById('customerSearch');
    const search = searchInput.value.trim().toLowerCase();

    let filtered = customers;
    if (search) {
        filtered = customers.filter(c =>
            c.name.toLowerCase().includes(search) || (c.phone && c.phone.includes(search))
        );
    }

    let totalDebts = 0, totalCollected = 0, indebtedCount = 0, paidCount = 0, partialCount = 0;
    const statsList = [];
    customers.forEach(c => {
        const stats = getCustomerStats(c.name);
        statsList.push({ ...c, ...stats });
        totalDebts += stats.remaining;
        totalCollected += stats.totalPaid;
        if (stats.status === 'دين كامل') indebtedCount++;
        else if (stats.status === 'دين جزئي') partialCount++;
        else if (stats.status === 'مسدد') paidCount++;
    });

    const sorted = statsList.sort((a, b) => {
        if (a.remaining > b.remaining) return -1;
        if (a.remaining < b.remaining) return 1;
        return a.name.localeCompare(b.name);
    });

    const statsContainer = document.getElementById('customerStatsContainer');
    statsContainer.innerHTML = `
        <div class="stat-card"><div class="stat-value">${totalDebts.toFixed(2)} $</div><div class="stat-label">إجمالي الديون</div></div>
        <div class="stat-card"><div class="stat-value">${indebtedCount + partialCount}</div><div class="stat-label">عملاء مدينين</div></div>
        <div class="stat-card"><div class="stat-value">${paidCount}</div><div class="stat-label">عملاء مسددين</div></div>
        <div class="stat-card"><div class="stat-value">${totalCollected.toFixed(2)} $</div><div class="stat-label">إجمالي المحصلات</div></div>
    `;

    if (filtered.length === 0) {
        container.innerHTML = `<div class="empty-state"><div class="empty-icon">👥</div><p>لا يوجد عملاء${search ? ' مطابقين للبحث' : ''}</p></div>`;
        return;
    }

    let html = `<table class="data-table"><thead><tr>
        <th>الاسم</th><th>الهاتف</th><th>إجمالي المشتريات</th><th>إجمالي المدفوع</th><th>المبلغ المتبقي</th><th>الحالة</th><th>الإجراءات</th>
    </tr></thead><tbody>`;

    sorted.forEach(c => {
        const statusBadge = c.status === 'مسدد'
            ? '<span class="badge badge-paid">مسدد</span>'
            : c.status === 'دين جزئي'
                ? '<span class="badge badge-partial">دين جزئي</span>'
                : '<span class="badge badge-unpaid">عليه ديون</span>';

        html += `<tr>
            <td><strong>${escHtml(c.name)}</strong></td>
            <td>${escHtml(c.phone || '-')}</td>
            <td>${c.totalInvoiced.toFixed(2)} $</td>
            <td>${c.totalPaid.toFixed(2)} $</td>
            <td><strong>${c.remaining.toFixed(2)} $</strong></td>
            <td>${statusBadge}</td>
            <td class="actions">
                <button class="btn btn-primary btn-xs" onclick="openCustomerDebt('${escHtml(c.name)}')">📋 تفاصيل</button>
                <button class="btn btn-warning btn-xs" onclick="editCustomer('${c.id}')">✏️ تعديل</button>
                <button class="btn btn-danger btn-xs" onclick="deleteCustomer('${c.id}')">🗑️ حذف</button>
            </td>
        </tr>`;
    });
    html += '</tbody></table>';
    container.innerHTML = html;
}

function openCustomerDebt(customerName) {
    const modal = document.getElementById('customerDebtModal');
    const content = document.getElementById('customerDebtContent');
    const stats = getCustomerStats(customerName);
    const customerInvoices = invoices.filter(inv => inv.customer === customerName);
    const customerPayments = paymentsLog.filter(p => p.customerName === customerName);

    let invRows = '';
    if (customerInvoices.length > 0) {
        customerInvoices.forEach(inv => {
            const net = inv.netTotal !== undefined ? inv.netTotal : (inv.subtotal - (inv.discountValue || 0));
            const paid = inv.payment || 0;
            const remaining = inv.remaining !== undefined ? inv.remaining : (net - paid);
            const status = remaining <= 0 ? 'مدفوعة' : (paid > 0 ? 'دين جزئي' : 'دين كامل');
            invRows += `<tr>
                <td>${inv.number}</td><td>${formatDateDisplay(inv.date)}</td><td>${net.toFixed(2)} $</td>
                <td>${paid.toFixed(2)} $</td><td><strong>${remaining.toFixed(2)} $</strong></td>
                <td>${status === 'مدفوعة' ? '<span class="badge badge-paid">مدفوعة</span>' : status === 'دين جزئي' ? '<span class="badge badge-partial">دين جزئي</span>' : '<span class="badge badge-unpaid">دين كامل</span>'}</td>
            </tr>`;
        });
    } else {
        invRows = `<tr><td colspan="6" class="empty-state">لا توجد فواتير لهذا العميل</td></tr>`;
    }

    let payRows = '';
    if (customerPayments.length > 0) {
        customerPayments.forEach(p => {
            const allocStr = p.allocations ? p.allocations.map(a => `${a.invoiceNumber}: ${a.amount.toFixed(2)} $`).join(' | ') : '—';
            payRows += `<tr>
                <td>${new Date(p.datetime).toLocaleString('ar-SA')}</td>
                <td>${p.amount.toFixed(2)} $</td>
                <td>${allocStr}</td>
                <td>${escHtml(p.notes || '—')}</td>
            </tr>`;
        });
    } else {
        payRows = `<tr><td colspan="4" class="empty-state">لا توجد دفعات مسجلة</td></tr>`;
    }

    content.innerHTML = `
        <h3 style="margin-bottom:16px;">تفاصيل العميل: ${escHtml(customerName)}</h3>
        <div class="debt-header">
            <div class="debt-summary">
                <div class="summary-item"><span class="summary-label">إجمالي المشتريات:</span><span class="summary-number">${stats.totalInvoiced.toFixed(2)} $</span></div>
                <div class="summary-item"><span class="summary-label">إجمالي المدفوع:</span><span class="summary-number">${stats.totalPaid.toFixed(2)} $</span></div>
                <div class="summary-item"><span class="summary-label">المبلغ المتبقي:</span><span class="summary-number" style="color:${stats.remaining > 0 ? 'red' : 'green'}">${stats.remaining.toFixed(2)} $</span></div>
            </div>
            <button class="btn btn-success" onclick="showAddPaymentForm('${escHtml(customerName)}')">➕ إضافة دفعة</button>
        </div>

        <h4>الفواتير</h4>
        <table class="data-table" style="margin-bottom:20px;">
            <thead><tr><th>الرقم</th><th>التاريخ</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th></tr></thead>
            <tbody>${invRows}</tbody>
        </table>

        <h4>سجل الدفعات</h4>
        <table class="payment-log-table">
            <thead><tr><th>التاريخ والوقت</th><th>المبلغ</th><th>توزيع على الفواتير</th><th>ملاحظات</th></tr></thead>
            <tbody>${payRows}</tbody>
        </table>

        <div id="addPaymentForm" style="margin-top:20px; display:none; border-top:1px solid #ccc; padding-top:15px;">
            <h4>إضافة دفعة جديدة</h4>
            <div class="form-grid">
                <div class="form-group"><label>المبلغ</label><input type="number" id="newPaymentAmount" min="0.01" step="0.01" value="${stats.remaining.toFixed(2)}"></div>
                <div class="form-group"><label>ملاحظات</label><input type="text" id="newPaymentNotes" placeholder="اختياري"></div>
            </div>
            <div class="form-actions">
                <button class="btn btn-success" onclick="submitNewPayment('${escHtml(customerName)}')">💾 حفظ الدفعة</button>
                <button class="btn btn-outline" onclick="hideAddPaymentForm()">إلغاء</button>
            </div>
        </div>
    `;

    modal.classList.add('show');
}

function closeCustomerDebtModal() {
    document.getElementById('customerDebtModal').classList.remove('show');
}
document.getElementById('customerDebtModal').addEventListener('click', function (e) {
    if (e.target === this) closeCustomerDebtModal();
});

function showAddPaymentForm(customerName) {
    document.getElementById('addPaymentForm').style.display = 'block';
}
function hideAddPaymentForm() {
    document.getElementById('addPaymentForm').style.display = 'none';
}
function submitNewPayment(customerName) {
    const amount = parseFloat(document.getElementById('newPaymentAmount').value) || 0;
    const notes = document.getElementById('newPaymentNotes').value.trim();
    addCustomerPayment(customerName, amount, notes);
}

// ============================================================
// إضافة/تعديل/حذف العملاء
// ============================================================
function openCustomerModal(data) {
    document.getElementById('customerModal').classList.add('show');
    if (data) {
        document.getElementById('customerModalTitle').textContent = 'تعديل العميل';
        document.getElementById('editCustomerId').value = data.id;
        document.getElementById('custName').value = data.name;
        document.getElementById('custPhone').value = data.phone || '';
        document.getElementById('custAddress').value = data.address || '';
    } else {
        document.getElementById('customerModalTitle').textContent = 'إضافة عميل جديد';
        document.getElementById('editCustomerId').value = '';
        document.getElementById('custName').value = '';
        document.getElementById('custPhone').value = '';
        document.getElementById('custAddress').value = '';
    }
}

function closeCustomerModal() {
    document.getElementById('customerModal').classList.remove('show');
}
document.getElementById('customerModal').addEventListener('click', function (e) {
    if (e.target === this) closeCustomerModal();
});

function saveCustomer() {
    const name = document.getElementById('custName').value.trim();
    const phone = document.getElementById('custPhone').value.trim();
    const address = document.getElementById('custAddress').value.trim();
    const editId = document.getElementById('editCustomerId').value;

    if (!name) { showToast('الرجاء إدخال اسم العميل', 'error'); return; }

    if (editId) {
        const idx = customers.findIndex(c => c.id === editId);
        if (idx === -1) { showToast('العميل غير موجود', 'error'); return; }
        customers[idx] = { ...customers[idx], name, phone, address };
        showToast('✅ تم تعديل العميل');
    } else {
        if (customers.some(c => c.name.toLowerCase() === name.toLowerCase())) {
            showToast('⚠️ هذا الاسم موجود مسبقاً', 'error');
            return;
        }
        customers.push({
            id: Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 4),
            name,
            phone,
            address,
            createdAt: new Date().toISOString()
        });
        showToast('✅ تم إضافة العميل');
    }
    saveAll();
    renderCustomers();
    updateCustomerList();
    closeCustomerModal();
}

function editCustomer(id) {
    const c = customers.find(c => c.id === id);
    if (!c) { showToast('العميل غير موجود', 'error'); return; }
    openCustomerModal(c);
}

function deleteCustomer(id) {
    if (!confirm('هل أنت متأكد من حذف هذا العميل؟')) return;
    customers = customers.filter(c => c.id !== id);
    saveAll();
    renderCustomers();
    updateCustomerList();
    showToast('تم حذف العميل');
}

// ============================================================
// النسخ الاحتياطي والاستيراد والحذف (محلياً)
// ============================================================
function exportBackup() {
    const backup = {
        invoices,
        customers,
        invoiceCounter,
        paymentsLog,
        itemsCatalog,
        exportedAt: new Date().toISOString()
    };
    const json = JSON.stringify(backup, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    showToast('✅ تم إنشاء النسخة الاحتياطية بنجاح');
}

function importBackup(event) {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function (e) {
        try {
            const data = JSON.parse(e.target.result);
            if (!data.invoices || !Array.isArray(data.invoices)) {
                throw new Error('ملف غير صالح');
            }
            invoices = data.invoices || [];
            customers = data.customers || [];
            invoiceCounter = data.invoiceCounter || 0;
            paymentsLog = data.paymentsLog || [];
            itemsCatalog = data.itemsCatalog || [];
            saveAll();
            renderInvoices();
            renderCustomers();
            updateCustomerList();
            updateHeaderTotal();
            showToast('✅ تم استيراد البيانات بنجاح');
        } catch (err) {
            showToast('❌ فشل استيراد البيانات: الملف غير صالح', 'error');
            console.error(err);
        }
    };
    reader.readAsText(file);
    event.target.value = '';
}

function deleteAllData() {
    document.getElementById('deleteConfirmModal').classList.add('show');
}

function closeDeleteConfirmModal() {
    document.getElementById('deleteConfirmModal').classList.remove('show');
}
document.getElementById('deleteConfirmModal').addEventListener('click', function (e) {
    if (e.target === this) closeDeleteConfirmModal();
});

function executeDeleteAllData() {
    if (!confirm('هل أنت متأكد تماماً؟ هذه آخر فرصة للتراجع.')) return;

    invoices = [];
    customers = [];
    invoiceCounter = 0;
    paymentsLog = [];
    itemsCatalog = [];
    saveAll();
    renderInvoices();
    renderCustomers();
    updateCustomerList();
    updateHeaderTotal();
    closeDeleteConfirmModal();
    showToast('✅ تم حذف جميع البيانات بنجاح');
}

// ============================================================
// أدوات مساعدة
// ============================================================
function escHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
}

function updateCustomerList() {
    const datalist = document.getElementById('customerList');
    const names = [...new Set(customers.map(c => c.name))];
    invoices.forEach(inv => {
        if (!names.includes(inv.customer)) names.push(inv.customer);
    });
    datalist.innerHTML = names.map(n => `<option value="${escHtml(n)}">`).join('');
}

function updateHeaderTotal() {
    const total = invoices.reduce((sum, inv) => {
        const net = inv.netTotal !== undefined ? inv.netTotal : (inv.subtotal - (inv.discountValue || 0));
        return sum + net;
    }, 0);
    document.getElementById('headerTotalSales').textContent = total.toFixed(2);
}

// ============================================================
// بدء التشغيل
// ============================================================
async function init() {
    await loadAllData();

    if (navigator.onLine && localStorage.getItem('pendingSync') === 'true') {
        await syncToFirebase();
    }

    logoBase64 = await loadLogoAsBase64();
    showSplash(logoBase64);

    document.getElementById('invDate').value = new Date().toISOString().split('T')[0];
    addItemRow();
    generateInvNumber();
    updateCustomerList();
    renderInvoices();
    renderCustomers();
    updateHeaderTotal();
    document.getElementById('paymentStatus').value = 'دين كامل';
    document.getElementById('paymentInput').disabled = true;
    calcInvoice();
}
init();
